SourceCode.Declaration:
/// <summary>
/// getOrdersForDate request. DeliveryDate is an ISO date (yyyy-MM-dd) in the device's own day; WarehouseId blank = every warehouse.
/// </summary>
[DataContractAttribute]
class HSMobileOpsOrdersForDateRequest
{
    DataAreaId dataAreaId;
    str        warehouseId;
    str        deliveryDate;

}

Method.Source:
[DataMemberAttribute('DataAreaId')]
public DataAreaId parmDataAreaId(DataAreaId _value = dataAreaId)
{
    dataAreaId = _value;
    return dataAreaId;
}

[DataMemberAttribute('WarehouseId')]
public str parmWarehouseId(str _value = warehouseId)
{
    warehouseId = _value;
    return warehouseId;
}

[DataMemberAttribute('DeliveryDate')]
public str parmDeliveryDate(str _value = deliveryDate)
{
    deliveryDate = _value;
    return deliveryDate;
}
